-- 5. SPEED LIMITS AND ROAD MARKINGS - 5 questions
-- ============================================================

('special', 'Jaka jest dopuszczalna prędkość pojazdu osobowego w terenie zabudowanym w Polsce?', 'Tốc độ cho phép của xe ô tô con trong khu vực đông dân cư ở Ba Lan là bao nhiêu?', 'https://upload.wikimedia.org/wikipedia/commons/thumb/7/71/PL_road_sign_B-33.svg/250px-PL_road_sign_B-33.svg.png', '50 km/h', '50 km/h', '60 km/h', '60 km/h', '70 km/h', '70 km/h', 'A', 'W terenie zabudowanym dopuszczalna prędkość w ciągu dnia wynosi 50 km/h. W nocy (od 23:00 do 5:00) obowiązuje ograniczenie 50 km/h z możliwością ograniczenia do 30 km/h przez zarządcę drogi.', 'Trong khu vực đông dân cư, tốc độ cho phép ban ngày là 50 km/h. Ban đêm (từ 23:00 đến 5:00) áp dụng giới hạn 50 km/h có thể giảm xuống 30 km/h theo quyết định của cơ quan quản lý đường.'),

('special', 'Jaka jest dopuszczalna prędkość na autostradzie w Polsce?', 'Tốc độ cho phép trên đường cao tốc ở Ba Lan là bao nhiêu?', 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c8/PL_road_sign_E-17a.svg/250px-PL_road_sign_E-17a.svg.png', '120 km/h', '120 km/h', '130 km/h', '130 km/h', '140 km/h', '140 km/h', 'C', 'Na autostradzie w Polsce dopuszczalna prędkość wynosi 140 km/h dla samochodów osobowych.', 'Trên đường cao tốc ở Ba Lan, tốc độ cho phép là 140 km/h đối với xe ô tô con.'),

('special', 'Jaka jest dopuszczalna prędkość na drodze ekspresowej w Polsce?', 'Tốc độ cho phép trên đường cao tốc loại express ở Ba Lan là bao nhiêu?', 'https://upload.wikimedia.org/wikipedia/commons/thumb/2/2e/PL_road_sign_E-17b.svg/250px-PL_road_sign_E-17b.svg.png', '100 km/h', '100 km/h', '110 km/h', '110 km/h', '120 km/h', '120 km/h', 'C', 'Na drodze ekspresowej (z dwoma jezdniami) dopuszczalna prędkość wynosi 120 km/h.', 'Trên đường express (có hai làn đường) tốc độ cho phép là 120 km/h.'),

('special', 'Co oznacza ta linia na jezdni?', 'Vạch kẻ trên đường này có ý nghĩa gì?', 'https://upload.wikimedia.org/wikipedia/commons/thumb/9/9d/PL_road_sign_P-1a.svg/250px-PL_road_sign_P-1a.svg.png', 'Linia ciągła - zakaz przejeżdżania', 'Vạch liền - cấm vượt qua', 'Linia przerywana - można wyprzedzać', 'Vạch đứt đoạn - được phép vượt', 'Linia ostrzegawcza', 'Vạch cảnh báo', 'A', 'Linia ciągła (P-1) oznacza zakaz przejeżdżania - nie wolno jej przekraczać ani najeżdżać na nią.', 'Vạch liền (P-1) có nghĩa là cấm vượt qua - không được phép vượt qua hoặc đè lên vạch.'),

('special', 'Co oznacza podwójna linia ciągła na jezdni?', 'Vạch liền kép trên đường có ý nghĩa gì?', 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/05/PL_road_sign_P-4.svg/250px-PL_road_sign_P-4.svg.png', 'Można wyprzedzać', 'Được phép vượt', 'Bezwzględny zakaz wyprzedzania', 'Cấm vượt tuyệt đối', 'Ostrzeżenie o niebezpieczeństwie', 'Cảnh báo nguy hiểm', 'B', 'Podwójna linia ciągła (P-4) oznacza bezwzględny zakaz wyprzedzania i przejeżdżania - obowiązuje cały czas, nawet jeśli nie ma znaku.', 'Vạch liền kép (P-4) cấm vượt tuyệt đối và cấm đi vào - có hiệu lực mọi lúc, ngay cả khi không có biển báo.'),

