-- ============================================================

('special', 'W Polsce obowiązuje ruch:', 'Ở Ba Lan áp dụng giao thông:', 'https://upload.wikimedia.org/wikipedia/commons/thumb/9/93/PL_road_sign_C-18.svg/250px-PL_road_sign_C-18.svg.png', 'Prawostronny', 'Bên phải', 'Lewostronny', 'Bên trái', 'Dwustronny', 'Hai bên', 'A', 'W Polsce obowiązuje ruch prawostronny - pojazdy poruszają się po prawej stronie jezdni, a kierownica znajduje się po lewej stronie pojazdu.', 'Ở Ba Lan áp dụng giao thông bên phải - xe chạy ở phía phải đường và vô lăng ở phía trái xe.'),

('special', 'Czy wolno wyprzedzać pojazd na przejściu dla pieszych?', 'Có được phép vượt xe trên vạch sang đường cho người đi bộ không?', 'https://upload.wikimedia.org/wikipedia/commons/thumb/4/4d/PL_road_sign_D-6.svg/250px-PL_road_sign_D-6.svg.png', 'Tak, jeśli nie ma pieszych', 'Có, nếu không có người đi bộ', 'Tak, jeśli pojazd jedzie wolno', 'Có, nếu xe chạy chậm', 'Nie, jest to zabronione', 'Không, bị cấm', 'C', 'Wyprzedzanie na przejściu dla pieszych jest bezwzględnie zabronione. Wyjątek: na przejściu bez oznakowania poziomego można wyprzedzać, ale ostrożnie.', 'Vượt xe trên vạch sang đường cho người đi bộ bị cấm tuyệt đối. Ngoại lệ: trên vạch sang đường không có vạch kẻ ngang có thể vượt nhưng phải cẩn thận.'),

('special', 'Czy kierujący pojazdem może używać telefonu bez zestawu głośnomówiącego?', 'Người lái xe có thể sử dụng điện thoại không có bộ loa ngoài không?', 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/0b/PL_road_sign_D-7.svg/250px-PL_road_sign_D-7.svg.png', 'Tak, bez ograniczeń', 'Có, không giới hạn', 'Nie, jest to zabronione', 'Không, bị cấm', 'Tak, tylko w korku', 'Có, chỉ khi tắc đường', 'B', 'W Polsce używanie telefonu bez zestawu głośnomówiącego podczas jazdy jest zabronione i grozi mandatem.', 'Ở Ba Lan, sử dụng điện thoại không có bộ loa ngoài khi lái xe là bị cấm và bị phạt.'),

('special', 'Kto ma pierwszeństwo na skrzyżowaniu równorzędnym w Polsce?', 'Ai có quyền ưu tiên tại ngã tư ngang nhau ở Ba Lan?', 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/1a/PL_road_sign_A-8.svg/250px-PL_road_sign_A-8.svg.png', 'Pojazd z prawej strony', 'Xe từ phía phải', 'Pojazd z lewej strony', 'Xe từ phía trái', 'Pojazd szybszy', 'Xe chạy nhanh hơn', 'A', 'Na skrzyżowaniu dróg równorzędnych w Polsce obowiązuje zasada prawej strony - pierwszeństwo ma pojazd nadjeżdżający z prawej strony.', 'Tại ngã tư các đường ngang nhau ở Ba Lan áp dụng quy tắc bên phải - xe đến từ phía phải có quyền ưu tiên.'),

('special', 'Czy wolno zawracać na autostradzie?', 'Có được quay đầu xe trên đường cao tốc không?', 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c8/PL_road_sign_E-17a.svg/250px-PL_road_sign_E-17a.svg.png', 'Tak, w wyznaczonych miejscach', 'Có, ở nơi quy định', 'Tak, na pasie awaryjnym', 'Có, trên làn khẩn cấp', 'Nie, jest to surowo zabronione', 'Không, bị cấm nghiêm ngặt', 'C', 'Zawracanie na autostradzie jest surowo zabronione. Nie wolno też cofać, jechać pod prąd ani zatrzymywać się poza wyznaczonymi miejscami.', 'Quay đầu xe trên đường cao tốc bị cấm nghiêm ngặt. Cũng không được lùi xe, đi ngược chiều hoặc dừng ngoài những nơi quy định.'),

-- ============================================================
-- 7. VEHICLE EQUIPMENT - 5 questions
-- ============================================================

('special', 'Co jest obowiązkowym wyposażeniem każdego samochodu osobowego w Polsce?', 'Đồ gì là thiết bị bắt buộc của mọi xe ô tô con ở Ba Lan?', 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/8e/PL_road_sign_C-9.svg/250px-PL_road_sign_C-9.svg.png', 'Apteczka pierwszej pomocy', 'Hộp sơ cứu', 'Trójkąt ostrzegawczy', 'Tam giác cảnh báo', 'Gaśnica', 'Bình chữa cháy', 'B', 'Trójkąt ostrzegawczy jest obowiązkowym wyposażeniem każdego samochodu osobowego w Polsce. Apteczka jest zalecana, gaśnica wymagana w niektórych przypadkach.', 'Tam giác cảnh báo là thiết bị bắt buộc của mọi xe ô tô con ở Ba Lan. Hộp sơ cứu được khuyến khích, bình chữa cháy bắt buộc trong một số trường hợp.'),

('special', 'Jaki minimalny bieżnik opony jest dopuszczalny w Polsce?', 'Độ sâu lốp tối thiểu được phép ở Ba Lan là bao nhiêu?', 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/0b/PL_road_sign_D-7.svg/250px-PL_road_sign_D-7.svg.png', '1,0 mm', '1,0 mm', '1,6 mm', '1,6 mm', '2,0 mm', '2,0 mm', 'B', 'Minimalna głębokość bieżnika opony w Polsce wynosi 1,6 mm. Poniżej tej wartości opona jest uznawana za zużytą i nie może być używana.', 'Độ sâu lốp tối thiểu ở Ba Lan là 1,6 mm. Dưới giá trị này lốp được coi là mòn và không được sử dụng.'),

('special', 'W jakich okresach roku w Polsce obowiązuje obowiązek używania świateł mijania?', 'Ở Ba Lan, vào những thời kỳ nào trong năm bắt buộc phải sử dụng đèn chiếu gần?', 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/3f/PL_road_sign_A-30.svg/250px-PL_road_sign_A-30.svg.png', 'Tylko zimą', 'Chỉ mùa đông', 'Cały rok, przez całą dobę', 'Cả năm, suốt ngày đêm', 'Tylko w nocy', 'Chỉ ban đêm', 'B', 'W Polsce obowiązek używania świateł mijania obowiązuje przez cały rok i całą dobę - także w dzień.', 'Ở Ba Lan, bắt buộc sử dụng đèn chiếu gần suốt cả năm và suốt ngày đêm - kể cả ban ngày.'),

('special', 'Jaki jest minimalny wiek osoby, która może prowadzić samochód osobowy z kategorią B w Polsce?', 'Tuổi tối thiểu của người có thể lái xe ô tô con hạng B ở Ba Lan là bao nhiêu?', 'https://upload.wikimedia.org/wikipedia/commons/thumb/2/2c/PL_road_sign_B-18.svg/250px-PL_road_sign_B-18.svg.png', '16 lat', '16 tuổi', '17 lat', '17 tuổi', '18 lat', '18 tuổi', 'C', 'Minimalny wiek do prowadzenia samochodu osobowego (kategoria B) w Polsce wynosi 18 lat. Wcześniej (17 lat) można uzyskać prawo jazdy, ale z ograniczeniami i pod nadzorem.', 'Tuổi tối thiểu để lái xe ô tô con (hạng B) ở Ba Lan là 18 tuổi. Trước đó (17 tuổi) có thể có bằng lái nhưng bị giới hạn và phải có người giám sát.'),

('special', 'Ile wynosi maksymalne dopuszczalne stężenie alkoholu we krwi kierowcy w Polsce?', 'Nồng độ cồn tối đa cho phép trong máu của người lái xe ở Ba Lan là bao nhiêu?', 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/06/PL_road_sign_B-5.svg/250px-PL_road_sign_B-5.svg.png', '0,0 promila', '0,0 phần nghìn', '0,2 promila', '0,2 phần nghìn', '0,5 promila', '0,5 phần nghìn', 'B', 'W Polsce obowiązuje limit 0,2 promila alkoholu we krwi. Od 2024 roku planowane jest zaostrzenie do 0,0 promila dla kierowców z krótkim stażem. Dla wszystkich kierowców obecnie 0,2‰.', 'Ở Ba Lan áp dụng giới hạn 0,2 phần nghìn cồn trong máu. Từ năm 2024 có kế hoạch siết chặt xuống 0,0 đối với lái xe mới. Hiện tại áp dụng 0,2‰ cho tất cả.'),

-- ============================================================
-- 8. ALCOHOL/DRUGS - 5 questions
-- ============================================================

('special', 'Co się stanie, jeśli kierowca zostanie złapany na jeździe pod wpływem alkoholu (powyżej 0,5 promila) w Polsce?', 'Điều gì sẽ xảy ra nếu người lái xe bị bắt lái xe khi có nồng độ cồn (trên 0,5 phần nghìn) ở Ba Lan?', 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/06/PL_road_sign_B-5.svg/250px-PL_road_sign_B-5.svg.png', 'Tylko mandat', 'Chỉ phạt tiền', 'Zatrzymanie prawa jazdy, mandat i kara pozbawienia wolności do 2 lat', 'Tước bằng, phạt tiền và phạt tù đến 2 năm', 'Tylko pouczenie', 'Chỉ nhắc nhở', 'B', 'Prowadzenie pojazdu w stanie nietrzeźwości (powyżej 0,5 promila) w Polsce jest przestępstwem - grozi kara pozbawienia wolności do 2 lat, utrata prawa jazdy i wysoki mandat.', 'Lái xe khi say rượu (trên 0,5 phần nghìn) ở Ba Lan là trọng tội - có thể bị phạt tù đến 2 năm, tước bằng lái và phạt tiền cao.'),

('special', 'Jak długo po wypiciu alkoholu nie powinno się prowadzić samochodu?', 'Bao lâu sau khi uống rượu thì không nên lái xe?', 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/06/PL_road_sign_B-5.svg/250px-PL_road_sign_B-5.svg.png', '1 godzinę', '1 giờ', '2-3 godziny', '2-3 giờ', 'Minimum 6-8 godzin', 'Tối thiểu 6-8 giờ', 'C', 'Alkohol pozostaje w organizmie przez wiele godzin. Standardowe piwo (0,5l) jest metabolizowane przez około 2-3 godziny, ale dla bezpieczeństwa zaleca się minimum 6-8 godzin przerwy przed prowadzeniem pojazdu.', 'Rượu còn trong cơ thể nhiều giờ. Một lon bia tiêu chuẩn (0,5l) được chuyển hóa trong khoảng 2-3 giờ, nhưng để an toàn nên chờ tối thiểu 6-8 giờ trước khi lái xe.'),

('special', 'Czy kierowca może odmówić badania alkomatem w Polsce?', 'Người lái xe có thể từ chối kiểm tra nồng độ cồn ở Ba Lan không?', 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/06/PL_road_sign_B-5.svg/250px-PL_road_sign_B-5.svg.png', 'Tak, bez konsekwencji', 'Có, không bị phạt', 'Tak, ale może zostać poddany badaniu krwi', 'Có, nhưng có thể bị xét nghiệm máu', 'Nie, to niemożliwe', 'Không, không thể', 'B', 'Kierowca ma prawo odmówić badania alkomatem, ale wtedy policja ma prawo skierować go na badanie krwi. Odmowa obu badań jest traktowana jako przyznanie się do winy.', 'Người lái xe có quyền từ chối kiểm tra nồng độ cồn bằng ống thổi, nhưng khi đó cảnh sát có quyền yêu cầu xét nghiệm máu. Từ chối cả hai bị coi là nhận tội.'),

('special', 'Które leki mogą wpływać na zdolność prowadzenia pojazdu?', 'Loại thuốc nào có thể ảnh hưởng đến khả năng lái xe?', 'https://upload.wikimedia.org/wikipedia/commons/thumb/d/dc/PL_road_sign_B-9.svg/250px-PL_road_sign_B-9.svg.png', 'Tylko antybiotyki', 'Chỉ kháng sinh', 'Leki uspokajające, nasenne i psychotropowe', 'Thuốc an thần, thuốc ngủ và thuốc tâm thần', 'Żadne leki', 'Không có thuốc nào', 'B', 'Leki uspokajające, nasenne, przeciwdepresyjne i psychotropowe mogą znacząco wpływać na zdolność prowadzenia pojazdu. Zawsze należy czytać ulotkę lub konsultować się z lekarzem.', 'Thuốc an thần, thuốc ngủ, thuốc chống trầm cảm và thuốc tâm thần có thể ảnh hưởng đáng kể đến khả năng lái xe. Luôn đọc tờ hướng dẫn hoặc tham khảo bác sĩ.'),

('special', 'Ile piwa (0,5 l, 5% alkoholu) trzeba wypić, aby przekroczyć limit 0,2 promila?', 'Cần uống bao nhiêu bia (0,5 l, 5% cồn) để vượt quá giới hạn 0,2 phần nghìn?', 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/06/PL_road_sign_B-5.svg/250px-PL_road_sign_B-5.svg.png', '5 piw', '5 lon bia', '1-2 piwa', '1-2 lon bia', '10 piw', '10 lon bia', 'B', 'Dla osoby o wadze ok. 70 kg już 1-2 piwa mogą spowodować przekroczenie limitu 0,2 promila. Czasami wystarczy nawet jedno piwo.', 'Đối với người nặng khoảng 70 kg, 1-2 lon bia có thể vượt quá giới hạn 0,2 phần nghìn. Đôi khi chỉ cần một lon bia.'),

-- ============================================================
-- 9. FIRST AID BASICS - 5 questions
-- ============================================================

('special', 'Co należy zrobić w pierwszej kolejności na miejscu wypadku drogowego?', 'Điều đầu tiên cần làm tại hiện trường tai nạn giao thông là gì?', 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/1a/PL_road_sign_A-8.svg/250px-PL_road_sign_A-8.svg.png', 'Natychmiast ewakuować poszkodowanych', 'Ngay lập tức sơ tán nạn nhân', 'Zabezpieczyć miejsce wypadku i wezwać pomoc', 'Bảo vệ hiện trường và gọi cứu hộ', 'Sprawdzić dokumenty', 'Kiểm tra giấy tờ', 'B', 'Pierwszy krok na miejscu wypadku to zabezpieczenie miejsca (włączenie świateł awaryjnych, ustawienie trójkąta) i wezwanie pomocy (tel. 112). Bezpieczeństwo jest najważniejsze.', 'Bước đầu tiên tại hiện trường tai nạn là bảo vệ hiện trường (bật đèn khẩn cấp, đặt tam giác cảnh báo) và gọi cứu hộ (số 112). An toàn là quan trọng nhất.'),

('special', 'Pod jaki numer należy dzwonić w razie wypadku drogowego w Polsce?', 'Số điện thoại nào cần gọi khi xảy ra tai nạn giao thông ở Ba Lan?', 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/1a/PL_road_sign_A-8.svg/250px-PL_road_sign_A-8.svg.png', '999', '999', '112', '112', '997', '997', 'B', 'Numer alarmowy w Polsce to 112 (europejski numer alarmowy). Można też dzwonić pod 997 (policja), 998 (straż pożarna), 999 (pogotowie).', 'Số khẩn cấp ở Ba Lan là 112 (số khẩn cấp châu Âu). Cũng có thể gọi 997 (cảnh sát), 998 (cứu hỏa), 999 (cấp cứu).'),

('special', 'Jak udrożnić drogi oddechowe u nieprzytomnej osoby?', 'Làm thế nào để thông đường thở cho người bất tỉnh?', 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/1a/PL_road_sign_A-8.svg/250px-PL_road_sign_A-8.svg.png', 'Ułożyć w pozycji siedzącej', 'Đặt ở tư thế ngồi', 'Odchylić głowę do tyłu i unieść brodę', 'Nghiêng đầu ra sau và nâng cằm', 'Położyć na brzuchu', 'Đặt nằm sấp', 'B', 'Aby udrożnić drogi oddechowe u nieprzytomnej osoby, należy odchylić głowę do tyłu i unieść brodę (tzw. rękoczyn Esmarcha).', 'Để thông đường thở cho người bất tỉnh, cần nghiêng đầu ra sau và nâng cằm (gọi là nghiệm pháp Esmarch).'),

('special', 'Jak często należy wykonywać masaż serca u osoby z zatrzymaniem krążenia?', 'Mỗi lần nên thực hiện ép tim ngoài lồng ngực cho người ngừng tuần hoàn như thế nào?', 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/1a/PL_road_sign_A-8.svg/250px-PL_road_sign_A-8.svg.png', '30 uciśnięć na 2 oddechy, 100-120/min', '30 lần ép cho 2 nhịp thở, 100-120/phút', '60 uciśnięć na 1 oddech', '60 lần ép cho 1 nhịp thở', '100 uciśnięć bez oddechów', '100 lần ép không thở', 'A', 'Standardowo wykonuje się 30 uciśnięć klatki piersiowej na 2 oddechy ratownicze, z częstotliwością 100-120 uciśnięć na minutę. Głębokość uciśnięć: 5-6 cm.', 'Tiêu chuẩn là 30 lần ép ngực cho 2 nhịp thở cấp cứu, với tần suất 100-120 lần/phút. Độ sâu ép: 5-6 cm.'),

('special', 'Co to jest pozycja bezpieczna (pozycja boczna ustalona)?', 'Tư thế an toàn (tư thế nằm nghiêng ổn định) là gì?', 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/1a/PL_road_sign_A-8.svg/250px-PL_road_sign_A-8.svg.png', 'Pozycja na plecach', 'Tư thế nằm ngửa', 'Pozycja na boku z głową odchyloną', 'Tư thế nằm nghiêng với đầu nghiêng ra sau', 'Pozycja na brzuchu', 'Tư thế nằm sấp', 'B', 'Pozycja boczna ustalona (pozycja bezpieczna) to pozycja na boku, która zapobiega zadławieniu i utrzymuje drożność dróg oddechowych u nieprzytomnej, oddychającej osoby.', 'Tư thế nằm nghiêng ổn định (tư thế an toàn) là tư thế nằm nghiêng giúp tránh nghẹn và duy trì thông đường thở cho người bất tỉnh nhưng còn thở được.'),

-- ============================================================
-- 10. ENVIRONMENTAL DRIVING (Eco-driving) - 5 questions
-- ============================================================

('special', 'Co to jest ekojazda?', 'Lái xe sinh thái là gì?', 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c3/PL_road_sign_C-13.svg/250px-PL_road_sign_C-13.svg.png', 'Jazda na pełnych obrotach silnika', 'Lái xe với ga hết cỡ', 'Styl jazdy zmniejszający zużycie paliwa i emisję spalin', 'Phong cách lái giảm tiêu hao nhiên liệu và khí thải', 'Jazda tylko po autostradzie', 'Chỉ lái xe trên đường cao tốc', 'B', 'Ekojazda to styl jazdy, który minimalizuje zużycie paliwa i emisję spalin. Obejmuje płynne przyspieszanie, unikanie gwałtownych hamowań i utrzymywanie stałej prędkości.', 'Lái xe sinh thái là phong cách lái giảm thiểu tiêu hao nhiên liệu và khí thải. Bao gồm tăng tốc êm, tránh phanh gấp và duy trì tốc độ ổn định.'),

('special', 'Która z poniższych praktyk jest elementem ekojazdy?', 'Thực hành nào sau đây là một phần của lái xe sinh thái?', 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c3/PL_road_sign_C-13.svg/250px-PL_road_sign_C-13.svg.png', 'Gwałtowne przyspieszanie', 'Tăng tốc đột ngột', 'Płynne przyspieszanie i hamowanie', 'Tăng tốc và phanh êm', 'Jazda na najwyższym biegu w mieście', 'Chạy số cao nhất trong thành phố', 'B', 'Ekojazda obejmuje płynne przyspieszanie i hamowanie, unikanie biegu jałowego, jazdę na najwyższym możliwym biegu i przewidywanie sytuacji na drodze.', 'Lái xe sinh thái bao gồm tăng tốc và phanh êm, tránh chạy không tải, chạy số cao nhất có thể và dự đoán tình huống trên đường.'),

('special', 'Jak prawidłowo hamować w ekojazdzie?', 'Cách phanh đúng trong lái xe sinh thái là gì?', 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c3/PL_road_sign_C-13.svg/250px-PL_road_sign_C-13.svg.png', 'Gwałtownie hamować', 'Phanh đột ngột', 'Hamować silnikiem i płynnie', 'Phanh bằng động cơ và êm', 'Nie hamować wcale', 'Không phanh', 'B', 'Ekojazda preferuje hamowanie silnikiem (zjeżdżanie na biegu) zamiast gwałtownego hamowania hamulcem. To oszczędza paliwo i zmniejsza zużycie hamulców.', 'Lái xe sinh thái ưu tiên phanh bằng động cơ (chạy xe bằng số thấp khi xuống dốc) thay vì phanh gấp bằng phanh. Tiết kiệm nhiên liệu và giảm mòn phanh.'),

('special', 'Co to jest Start-Stop w samochodzie?', 'Hệ thống Start-Stop trên xe ô tô là gì?', 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c3/PL_road_sign_C-13.svg/250px-PL_road_sign_C-13.svg.png', 'System grzewczy', 'Hệ thống sưởi', 'System automatycznie wyłączający silnik na postoju', 'Hệ thống tự động tắt máy khi dừng', 'System klimatyzacji', 'Hệ thống điều hòa', 'B', 'System Start-Stop automatycznie wyłącza silnik, gdy pojazd stoi (np. na światłach) i uruchamia go ponownie po naciśnięciu sprzęgła lub gazu. Oszczędza paliwo i zmniejsza emisję.', 'Hệ thống Start-Stop tự động tắt máy khi xe dừng (ví dụ tại đèn đỏ) và khởi động lại khi nhấn côn hoặc ga. Tiết kiệm nhiên liệu và giảm khí thải.'),

('special', 'W jakiej temperaturze silnik spala najmniej paliwa?', 'Ở nhiệt độ nào động cơ tiêu hao nhiên liệu ít nhất?', 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c3/PL_road_sign_C-13.svg/250px-PL_road_sign_C-13.svg.png', 'Zaraz po uruchomieniu', 'Ngay sau khi khởi động', 'Po rozgrzaniu do temperatury roboczej', 'Sau khi làm nóng đến nhiệt độ hoạt động', 'W niskiej temperaturze', 'Ở nhiệt độ thấp', 'B', 'Silnik spala najmniej paliwa po rozgrzaniu do temperatury roboczej (ok. 90°C). Zimny silnik zużywa znacznie więcej paliwa, dlatego nie zaleca się długiego rozgrzewania na postoju.', 'Động cơ tiêu hao nhiên liệu ít nhất sau khi làm nóng đến nhiệt độ hoạt động (khoảng 90°C). Động cơ lạnh tiêu hao nhiều nhiên liệu hơn nhiều, vì vậy không nên làm nóng lâu khi dừng.');

